class _OrderScreenState extends State<OrderScreen> {
  int _secondsLeft = 600; // a Timer calls setState every second
  late Future<Order> _order;

  @override
  void initState() {
    super.initState();
    _order = api.fetchOrder(widget.orderId); // once per State
  }

  @override
  void didUpdateWidget(OrderScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.orderId == oldWidget.orderId) return;
    _order = api.fetchOrder(widget.orderId); // another order: new request
  }

  @override
  Widget build(BuildContext context) => Column(children: [
        Text('Arrives in $_secondsLeft s'),
        FutureBuilder<Order>(future: _order, builder: orderCard),
      ]);
}
